// SPDX-License-Identifier: MIT

pragma solidity ^0.8.0;

import "src/openzeppelin-solidity/contracts/token/ERC721/ERC721.sol";
import "src/openzeppelin-solidity/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "src/openzeppelin-solidity/contracts/access/Ownable.sol";
import "src/openzeppelin-solidity/contracts/utils/math/SafeMath.sol";
import "src/openzeppelin-solidity/contracts/utils/Strings.sol";

import "./common/meta-transactions/ContentMixin.sol";
import "./common/meta-transactions/NativeMetaTransaction.sol";

contract OwnableDelegateProxy {}

contract ProxyRegistry {
  mapping(address => OwnableDelegateProxy) public proxies;
}

/**
 * @title ERC721TradableJulia
 * ERC721TradableJulia - ERC721 contract that whitelists a trading address, and has minting functionality.
 */
abstract contract ERC721TradableJulia is
  ContextMixin,
  ERC721Enumerable,
  NativeMetaTransaction,
  Ownable
{
  using SafeMath for uint256;

  address proxyRegistryAddress;
  uint256 internal _currentTokenId = 0;
  uint256 public totalUnveiled = 0;
  uint256 public constant maximumPieces = 4200; // 1978 * 2 + 128 + 50 + 66

  event Unveiled(uint256 tokenId, address receiver);

  constructor(
    string memory _name,
    string memory _symbol,
    address _proxyRegistryAddress
  ) ERC721(_name, _symbol) {
    proxyRegistryAddress = _proxyRegistryAddress;
    _initializeEIP712(_name);
  }

  function remaining() public view returns (uint256 _remaining) {
    if (maximumPieces > totalUnveiled) {
      return maximumPieces - totalUnveiled;
    } else {
      return 0;
    }
  }

  /**
   * @dev Mints a token to an address with a tokenURI.
   * @param _to address of the future owner of the token
   */
  function mintTo(address _to) internal {
    require(remaining() > 0, "Supply limit reached");
    uint256 newTokenId = _getNextTokenId();
    _mint(_to, newTokenId);
    _incrementTokenId();
    totalUnveiled += 1;
    emit Unveiled(newTokenId, _to);
  }

  /**
   * @dev calculates the next token ID based on value of _currentTokenId
   * @return uint256 for the next token ID
   */
  function _getNextTokenId() private view returns (uint256) {
    return _currentTokenId.add(1);
  }

  /**
   * @dev increments the value of _currentTokenId
   */
  function _incrementTokenId() private {
    _currentTokenId++;
  }

  function baseTokenURI() public pure virtual returns (string memory);

  function tokenURI(uint256 _tokenId)
    public
    pure
    override
    returns (string memory)
  {
    return string(abi.encodePacked(baseTokenURI(), Strings.toString(_tokenId)));
  }

  /**
   * Override isApprovedForAll to whitelist user's OpenSea proxy accounts to enable gas-less listings.
   */
  function isApprovedForAll(address owner, address operator)
    public
    view
    override
    returns (bool)
  {
    // Whitelist OpenSea proxy contract for easy trading.
    ProxyRegistry proxyRegistry = ProxyRegistry(proxyRegistryAddress);
    if (address(proxyRegistry.proxies(owner)) == operator) {
      return true;
    }

    return super.isApprovedForAll(owner, operator);
  }

  /**
   * This is used instead of msg.sender as transactions won't be sent by the original token owner, but by OpenSea.
   */
  function _msgSender() internal view override returns (address sender) {
    return ContextMixin.msgSender();
  }
}

